CREATE TABLE parishes ( id TEXT PRIMARY KEY, name TEXT NOT NULL, full_name TEXT, jurisdiction TEXT NOT NULL CHECK(jurisdiction IN ('antiochian','greek','serbian','russian','romanian','macedonian','other')), address TEXT, lat REAL NOT NULL, lng REAL NOT NULL, timezone TEXT NOT NULL DEFAULT 'Australia/Sydney', website TEXT, phone TEXT, email TEXT, logo_path TEXT, acronym TEXT, chant_style TEXT, languages TEXT NOT NULL DEFAULT '["English"]', color TEXT, live_url TEXT, donation_url TEXT, raffle_url TEXT, payment_url TEXT, gala_url TEXT, info_source_type TEXT CHECK(info_source_type IN ('website','person','import')), info_source_ref TEXT, info_verified_at TEXT );
INSERT INTO parishes (id, name, jurisdiction, address, lat, lng, info_source_type, info_source_ref) VALUES ('_unassigned', 'Unassigned / Unknown Parish', 'other', 'Sydney NSW', -33.8688, 151.2093, 'import', 'schema baseline');
CREATE TABLE schedules ( id INTEGER PRIMARY KEY AUTOINCREMENT, parish_id TEXT NOT NULL REFERENCES parishes(id), day_of_week INTEGER NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), start_time TEXT NOT NULL, end_time TEXT, title TEXT NOT NULL, event_type TEXT NOT NULL DEFAULT 'liturgy', active INTEGER NOT NULL DEFAULT 1, languages TEXT, week_of_month TEXT, concurrent INTEGER NOT NULL DEFAULT 0, hide_live INTEGER NOT NULL DEFAULT 0, parish_scoped INTEGER NOT NULL DEFAULT 0, effective_from TEXT, effective_to TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) );
CREATE INDEX idx_schedules_parish ON schedules(parish_id);
CREATE INDEX idx_schedules_active ON schedules(active);
CREATE TABLE events ( id INTEGER PRIMARY KEY AUTOINCREMENT, parish_id TEXT NOT NULL REFERENCES parishes(id), source_adapter TEXT NOT NULL, schedule_id INTEGER REFERENCES schedules(id), title TEXT NOT NULL, description TEXT, start_utc TEXT NOT NULL, end_utc TEXT, location_override TEXT, lat REAL, lng REAL, event_type TEXT NOT NULL DEFAULT 'other', source_url TEXT, source_hash TEXT, status TEXT NOT NULL DEFAULT 'approved' CHECK(status IN ('approved','replaced','cancelled','hidden','rejected')), mutation_type TEXT NOT NULL DEFAULT 'scheduled', languages TEXT, poster_path TEXT, hide_live INTEGER NOT NULL DEFAULT 0, parish_scoped INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')) );
CREATE UNIQUE INDEX idx_events_source_hash ON events(source_hash);
CREATE INDEX idx_events_parish ON events(parish_id);
CREATE INDEX idx_events_start ON events(start_utc);
CREATE INDEX idx_events_status ON events(status);
CREATE INDEX idx_events_schedule ON events(schedule_id);
CREATE TABLE schedule_overrides ( id INTEGER PRIMARY KEY AUTOINCREMENT, schedule_id INTEGER NOT NULL REFERENCES schedules(id) ON DELETE CASCADE, occurrence_date TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('modified','cancelled','combined','hidden')), patch_title TEXT, patch_start_time TEXT, patch_end_time TEXT, patch_event_type TEXT, patch_languages TEXT, patch_feast TEXT, patch_description TEXT, patch_location_override TEXT, patch_hide_live INTEGER, patch_parish_scoped INTEGER, combined_into_event_id INTEGER REFERENCES events(id) ON DELETE CASCADE, note TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), UNIQUE(schedule_id, occurrence_date) );
CREATE INDEX idx_overrides_schedule ON schedule_overrides(schedule_id);
CREATE INDEX idx_overrides_combined ON schedule_overrides(combined_into_event_id);
CREATE INDEX idx_overrides_date ON schedule_overrides(occurrence_date);
CREATE TABLE event_parishes ( event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, parish_id TEXT NOT NULL REFERENCES parishes(id), PRIMARY KEY (event_id, parish_id) );
CREATE TABLE event_replaces ( replacing_event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, replaced_event_id INTEGER NOT NULL REFERENCES events(id), PRIMARY KEY (replacing_event_id, replaced_event_id) );
CREATE INDEX idx_event_replaces_replaced ON event_replaces(replaced_event_id);
CREATE TABLE adapter_runs ( id INTEGER PRIMARY KEY AUTOINCREMENT, adapter_id TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), finished_at TEXT, status TEXT NOT NULL DEFAULT 'running' CHECK(status IN ('running','success','failed')), events_found INTEGER NOT NULL DEFAULT 0, events_created INTEGER NOT NULL DEFAULT 0, events_updated INTEGER NOT NULL DEFAULT 0, error_message TEXT );
CREATE INDEX idx_adapter_runs_lookup ON adapter_runs(adapter_id, started_at DESC);
